#!/usr/bin/env bash
# Resolve env/geo.yml into env/geo-linux-64.lock inside a throwaway container.
set -euo pipefail
cd "$(dirname "$0")"
docker run --rm -v "$PWD":/env -w /env ubuntu:26.04 bash -ec '
  export DEBIAN_FRONTEND=noninteractive MAMBA_ROOT_PREFIX=/opt/mamba
  apt-get update -qq >/dev/null && apt-get install -y -qq --no-install-recommends ca-certificates bzip2 curl >/dev/null 2>&1
  curl -fsSL https://micro.mamba.pm/api/micromamba/linux-64/2.3.3 | tar -xj -C /usr/local bin/micromamba
  micromamba create -y -q -p /opt/geo -f geo.yml >/dev/null
  { echo "# Generated by env/lock.sh from env/geo.yml — do not edit by hand."
    micromamba env export -p /opt/geo --explicit --md5 | grep -v "^#"; } > geo-linux-64.lock
  chown '"$(id -u):$(id -g)"' geo-linux-64.lock'
echo "wrote env/geo-linux-64.lock ($(grep -c '^https' geo-linux-64.lock) packages)"
